shader_type canvas_item;

// Parametri visibili nell'Inspector e modificabili da codice
uniform float flash_modifier : hint_range(0.0, 1.0) = 0.0;
uniform vec4 flash_color : source_color = vec4(1.0, 1.0, 1.0, 1.0);

void fragment() {
	// Legge il colore originale del pixel alle coordinate UV attuali
	vec4 color = texture(TEXTURE, UV);

	// Mescola il colore RGB originale con il colore del flash in base al valore di flash_modifier
	vec3 mixed_rgb = mix(color.rgb, flash_color.rgb, flash_modifier);

	// Assegna il colore finale mantenendo la trasparenza (alpha) originale dello sprite
	COLOR = vec4(mixed_rgb, color.a);
}

# Esempio di gestione del colpo subito nel codice del personaggio
extends CharacterBody2D

@onready var sprite: Sprite2D = $Sprite2D


func take_damage() -> void:
	if sprite.material is ShaderMaterial:
		var mat := sprite.material as ShaderMaterial
		# Imposta il valore del flash al massimo (1.0 = completamente bianco)
		mat.set_shader_parameter("flash_modifier", 1.0)

		# Sfuma il valore fino a 0.0 nel giro di 0.2 secondi con un Tween
		var tween := create_tween()
		tween.tween_property(mat, "shader_parameter/flash_modifier", 0.0, 0.2)

shader_type canvas_item;

uniform vec4 line_color : source_color = vec4(1.0, 1.0, 0.0, 1.0); // Colore del contorno
uniform float line_thickness : hint_range(0.0, 10.0) = 1.0;

void fragment() {
	vec4 color = texture(TEXTURE, UV);

	// Se il pixel attuale è trasparente, verifichiamo i pixel vicini
	if (color.a == 0.0) {
		vec2 size = TEXTURE_PIXEL_SIZE * line_thickness;

		// Legge l'opacità dei 4 pixel adiacenti nelle 4 direzioni principali
		float alpha_up = texture(TEXTURE, UV + vec2(0.0, -size.y)).a;
		float alpha_down = texture(TEXTURE, UV + vec2(0.0, size.y)).a;
		float alpha_left = texture(TEXTURE, UV + vec2(-size.x, 0.0)).a;
		float alpha_right = texture(TEXTURE, UV + vec2(size.x, 0.0)).a;

		// Se almeno uno dei pixel vicini è visibile, disegna il colore del contorno
		float max_neighbor_alpha = max(max(alpha_up, alpha_down), max(alpha_left, alpha_right));
		if (max_neighbor_alpha > 0.0) {
			COLOR = line_color;
		} else {
			COLOR = color;
		}
	} else {
		COLOR = color;
	}
}
